'use strict';
// UX17/UX18: SQL-verified synthetic responses generated by backend ux17-operational-metrics-mysql.js.
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const assert = require('node:assert/strict');
const { chromium } = require('@playwright/test');
const compiler = require('vue-template-compiler');
const root = path.resolve(__dirname, '../..');
const option = name => { const index = process.argv.indexOf(name); return index >= 0 ? process.argv[index + 1] : null; };
const workspaceEvidence = path.resolve(root, '../docs/dashboard-ux/evidence/UX18');
const evidence = path.resolve(option('--output-dir') || (fs.existsSync(path.dirname(path.dirname(workspaceEvidence))) ? workspaceEvidence : path.join(os.tmpdir(), 'medsync-ux17-evidence')));
const input = path.resolve(option('--fixtures') || path.join(workspaceEvidence, 'calculated-fixtures.json'));
if (!fs.existsSync(input)) throw new Error('Run backend ux17-operational-metrics-mysql.js --output <file> first, then pass --fixtures <file>.');
const fixtures = JSON.parse(fs.readFileSync(input, 'utf8'));
const parsed = compiler.parseComponent(fs.readFileSync(path.join(root, 'src/views/Dashboard/components/DashboardOperationalSummary.vue'), 'utf8'));
assert.deepEqual(compiler.compile(parsed.template.content).errors, []);
const metrics = fs.readFileSync(path.join(root, 'src/domain/dashboard/metrics.js'), 'utf8').replace(/export /g, '');
const component = parsed.script.content.replace(/^import .*;\r?\n/gm, '').replace('export default', 'window.OperationalSummary =');
(async () => {
    fs.mkdirSync(evidence, { recursive: true });
    const browser = await chromium.launch({ headless: true, channel: 'msedge' });
    const page = await browser.newPage();
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    try {
        await page.route('**/*', route => route.abort());
        await page.setContent('<!doctype html><html lang="es"><head><meta charset="utf-8"></head><body><div id="app"></div></body></html>');
        await page.addStyleTag({ path: path.join(root, 'node_modules/vuetify/dist/vuetify.min.css') });
        await page.addStyleTag({ content: 'body{margin:0}.qa-wrap{max-width:1248px;margin:0 auto;padding:16px}' + parsed.styles.map(style => style.content).join('\n') });
        await page.addScriptTag({ path: path.join(root, 'node_modules/vue/dist/vue.js') });
        await page.addScriptTag({ path: path.join(root, 'node_modules/vuetify/dist/vuetify.js') });
        await page.evaluate(({ metrics, component, template, initial }) => {
            (0, eval)(metrics); (0, eval)(component);
            window.OperationalSummary.template = template;
            window.readingApp = new window.Vue({ vuetify: new window.Vuetify(), data: { metricData: initial },
                render: function(h) {
                    return h('v-app', [h('main', { class: 'qa-wrap' }, [h(window.OperationalSummary, { ref: 'operations', props: { data: this.metricData } })])]);
                }
            }).$mount('#app');
        }, { metrics, component, template: parsed.template.content, initial: fixtures.empty });
        const measurements = [];
        for (const [viewport, width, height] of [['desktop', 1440, 1000], ['mobile', 390, 844]]) {
            await page.setViewportSize({ width, height });
            for (const state of ['empty', 'active', 'clear', 'overdueOnly', 'upcomingOnly', 'boundary']) {
                await page.evaluate(async data => { window.readingApp.metricData = data; await window.Vue.nextTick(); }, fixtures[state]);
                const values = await page.evaluate(() => {
                    const op = window.readingApp.$refs.operations;
                    return { keys: op.priorityActions.map(item => item.key), values: op.priorityActions.map(item => item.value),
                        tones: op.priorityActions.map(item => item.tone), pendingFollowUps: op.pendingFollowUps,
                        overdue: op.overdueFollowUps, upcoming: op.upcomingFollowUps,
                        overdueCard: op.decisionCards.find(card => card.key === 'followUpsOverdue').value,
                        upcomingCard: op.decisionCards.find(card => card.key === 'followUpsUpcoming').value,
                        retention: op.decisionCards.find(card => card.key === 'retention').value,
                        noShow: op.decisionCards.find(card => card.key === 'noShow').value,
                        cost: op.economicsCards[0].value, viewport: innerWidth, content: document.documentElement.scrollWidth };
                });
                assert.ok(values.content <= values.viewport + 1, viewport + '/' + state + ' has no horizontal overflow');
                if (state === 'empty') {
                    assert.deepEqual(values.keys, ['insufficient']); assert.deepEqual(values.tones, ['neutral']);
                    assert.equal(values.retention, 'No disponible');
                    assert.equal(await page.getByText('Sin pendientes detectados', { exact: true }).count(), 0);
                    await page.getByText('Aún no hay datos suficientes', { exact: true }).waitFor();
                } else if (state === 'active') {
                    assert.deepEqual(values.keys, ['pendingConfirmations', 'overdueFollowUps', 'clinicalPending']);
                    assert.deepEqual(values.values, ['1 pendiente', '1 sin cita', '1 pendiente']);
                    assert.equal(values.pendingFollowUps, 1); assert.equal(values.retention, '50%');
                    assert.equal(values.noShow, '8.3%'); assert.equal(values.cost, '$200');
                } else if (state === 'clear') {
                    assert.deepEqual(values.keys, ['steady']); assert.deepEqual(values.tones, ['success']);
                    await page.getByText('Sin pendientes detectados', { exact: true }).waitFor();
                } else if (state === 'overdueOnly') {
                    assert.deepEqual(values.keys, ['overdueFollowUps']);
                    assert.deepEqual(values.values, ['1 sin cita']);
                    assert.equal(values.overdue, 1); assert.equal(values.upcoming, 0);
                    await page.getByText('Recupera seguimientos vencidos', { exact: true }).waitFor();
                } else if (state === 'upcomingOnly') {
                    assert.deepEqual(values.keys, ['steady']); assert.deepEqual(values.tones, ['success']);
                    assert.equal(values.overdueCard, '0'); assert.equal(values.upcomingCard, '2');
                    await page.getByText('Sin pendientes prioritarios detectados', { exact: true }).waitFor();
                    assert.equal(await page.getByText('Recupera seguimientos vencidos', { exact: true }).count(), 0);
                    await page.getByText('Próximos seguimientos sin cita', { exact: true }).waitFor();
                } else if (state === 'boundary') {
                    assert.equal(values.keys[0], 'overdueFollowUps'); assert.equal(values.values[0], '9 sin cita');
                    assert.equal(values.overdueCard, '9'); assert.equal(values.upcomingCard, '3');
                }
                await page.locator('.priority-panel').screenshot({ path: path.join(evidence, 'reading-' + state + '-' + viewport + '.png') });
                if (['upcomingOnly', 'boundary'].includes(state)) await page.locator('.decision-panel').screenshot({ path: path.join(evidence, 'counts-' + state + '-' + viewport + '.png') });
                measurements.push({ viewport, state, content: values.content, keys: values.keys });
            }
        }
        await page.evaluate(async () => { window.readingApp.metricData = { decisionMetrics: { followUps: { available: false, due: null, scheduled: null } } }; await window.Vue.nextTick(); });
        assert.equal(await page.locator('.priority-panel').count(), 0, 'Unavailable data cannot produce a green message');
        assert.deepEqual(errors, []);
        console.log(JSON.stringify({ result: 'PASS', measurements, sqlToVueValues: 'PASS', errors, network: 'blocked' }, null, 2));
    } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
